// Animation - Page Loader
function initLoader() {

  var tl = gsap.timeline();

  tl.call(function () {
    scroll.stop();
  }, null, 0);

  tl.call(function () {
    pageTransitionOut();
  }, null, 0.1);

  tl.to($('.loading-screen'), {
    autoAlpha: 0,
    ease: "primary-ease",
    duration: durationDefault
  }, 0.1);

}

// Animation - Page Leave
function pageTransitionIn() {
  var tl = gsap.timeline();

  if (document.querySelector('.lorem-ipsum')) {}

  tl.call(function () {
    scroll.stop();
  });
  
  tl.to($('.loading-screen'), {
    autoAlpha: 1,
    ease: "Power1.easeOut",
    duration: 0.5
  });
  
  tl.to($('.loading-screen'), {
    autoAlpha: 0,
    ease: "Power1.easeIn",
    duration: 0.5,
    delay: 0.1
  });
}

// Animation - Page Enter
function pageTransitionOut() {
  var tl = gsap.timeline();

  tl.call(function () {
    scroll.start();
  }, null, 0);

  tl.from($('[data-transition-animation="fade-in"]'), {
    y: "2em",
    rotate: 0.001,
    opacity: 0,
    ease: "primary-ease",
    duration: durationDefault,
    stagger: staggerDefault,
    clearProps: "all"
  }, 0);

  tl.from($('[data-transition-animation="words"] .single-word-inner'), {
    yPercent: 105,
    rotate: 0.001,
    ease: "primary-ease",
    duration: durationDefault,
    stagger: staggerDefault,
    clearProps: "all"
  }, 0);

  if (document.querySelector('.header-bg')) {
    tl.from($('.header-bg'), {
      scale: 1.25,
      rotate: 0.001,
      ease: "primary-ease",
      duration: durationDefault,
      stagger: staggerDefault,
      clearProps: "all"
    }, 0);
  }

}

function initPageTransitions() {

  // Reset scroll on page next
  history.scrollRestoration = "manual";

  barba.hooks.afterEnter(() => {
    const shouldReturnToCases = sessionStorage.getItem("returnToCasesAnchor") === "true";
    const isHomePage = window.location.pathname === "/" || window.location.pathname === "/home";
    const hasCasesSection = document.querySelector("#cases");
  
    if (shouldReturnToCases && isHomePage && hasCasesSection) {
      scroll.scrollTo("#cases", {
        immediate: true,
        force: true,
        offset: 0
      });
  
      sessionStorage.removeItem("returnToCasesAnchor");
    } else {
      window.scrollTo(0, 0);
    }
  
    ScrollTrigger.refresh();
  });

  barba.hooks.leave(() => {
    initBasicFunctions();
  });

  // Functions Before
  function initResetDataBefore() {
    $('[data-navigation-status]').attr('data-navigation-status', 'not-active');
  }

  // Functions After
  function initResetDataAfter() {
    $('[data-navigation-status]').attr('data-navigation-status', 'not-active');
    $('[data-scrolling-direction]').attr('data-scrolling-direction', 'down');
    $('[data-scrolling-started]').attr('data-scrolling-started', 'false');
  }

  barba.init({
    sync: true,
    debug: true,
    timeout: 7000,
    transitions: [{
      name: 'self',
      async leave(data) {
        
        if (data.current.url.path.includes("/work/") && (data.next.url.path === "/" || data.next.url.path === "/home")) {
          sessionStorage.setItem("returnToCasesAnchor", "true");
        }

        pageTransitionIn(data.current);
        initResetDataBefore();
        await delay(transitionOffset);
        initBarbaNavUpdate(data);
        initResetDataAfter();
        scroll.destroy();
        data.current.container.remove();
      },
      async enter(data) {
        pageTransitionOut(data.next);
      },
      async beforeEnter(data) {
        ScrollTrigger.getAll().forEach(t => t.kill());
        initResetWebflow(data);
        initSmoothScroll(data.next.container);
        initScript();
      },
    }, {
      name: 'default',
      once(data) {
        initSmoothScroll(data.next.container);
        initScript();
        initLoader();
      },
      async leave(data) {
        
        if (data.current.url.path.includes("/work/") && (data.next.url.path === "/" || data.next.url.path === "/home")) {
          sessionStorage.setItem("returnToCasesAnchor", "true");
        }
        
        pageTransitionIn(data.current);
        initResetDataBefore();
        await delay(transitionOffset);
        initBarbaNavUpdate(data);
        initResetDataAfter();
        scroll.destroy();
        data.current.container.remove();
      },
      async enter(data) {
        pageTransitionOut(data.next);
      },
      async beforeEnter(data) {
        ScrollTrigger.getAll().forEach(t => t.kill());
        initResetWebflow(data);
        initSmoothScroll(data.next.container);
        initScript();
      },
    }]
  });

  function initSmoothScroll(container) {
    initLenis();
    ScrollTrigger.refresh();
  }
}

function initLenis() {

  // Lenis: https://github.com/studio-freight/lenis
  scroll = new Lenis({
    // duration: 1
  });

  scroll.on('scroll', ScrollTrigger.update);

  gsap.ticker.add((time) => {
    scroll.raf(time * 1000);
  });

  gsap.ticker.lagSmoothing(0);
}

// Don't touch
function delay(n) {
  n = n || 2000;
  return new Promise((done) => {
    setTimeout(() => {
      done();
    }, n);
  });
}

