/**
 * Mondriaan slider
 */
function initMondriaanSlider() {
  const directions = {
    'left-right': { axis: 'x', multiplier: -1 },
    'right-left': { axis: 'x', multiplier: 1 },
    'top-bottom': { axis: 'y', multiplier: -1 },
    'bottom-top': { axis: 'y', multiplier: 1 },
  };

  const directionKeys = Object.keys(directions);

  document.querySelectorAll('[data-mondriaan-slider]').forEach((slider) => {
    const subSliders = Array.from(
      slider.querySelectorAll('[data-mondriaan-sub-slider]')
    );

    let currentIndex = 0;
    let previousIndex = 0;
    let isAnimating = false;

    const previousDirections = {};
    const colors = [];

    const colorItems = slider.querySelectorAll(
      '[data-mondriaan-slider-colors] [data-mondriaan-slider-color]'
    );

    colorItems.forEach((item) => {
      const styles = window.getComputedStyle(item);
      const backgroundColor = styles.backgroundColor;
      const textColor = styles.color;

      colors.push({
        backgroundColor:
          backgroundColor && backgroundColor !== 'rgba(0, 0, 0, 0)'
            ? backgroundColor
            : null,
        textColor: textColor || null,
      });
    });

    const firstSubSlider = subSliders[0];
    const totalSlides = firstSubSlider
      ? firstSubSlider.querySelectorAll('[data-mondriaan-slider-slide]').length
      : 0;

    const totalCountEl = slider.querySelector('[data-mondriaan-slider-total]');

    if (totalCountEl) {
      totalCountEl.textContent = String(totalSlides).padStart(2, '0');
    }

    subSliders.forEach((subSlider, subSliderIndex) => {
      const slides = Array.from(
        subSlider.querySelectorAll('[data-mondriaan-slider-slide]')
      );
      const directionAttr = subSlider.getAttribute('data-mondriaan-sub-slider');

      slides.forEach((slide, slideIndex) => {
        const countEls = slide.querySelectorAll('[data-mondriaan-slider-count]');

        countEls.forEach((countEl) => {
          countEl.textContent = String(slideIndex + 1).padStart(2, '0');
        });
      });

      if (directionAttr === 'random') {
        previousDirections[subSliderIndex] = null;
      }

      if (directionAttr === 'fade') {
        slides.forEach((slide, index) => {
          gsap.set(slide, {
            autoAlpha: index === 0 ? 1 : 0,
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
          });
        });
      } else {
        slides.forEach((slide, index) => {
          gsap.set(slide, {
            x: 0,
            y: 0,
            display: index === 0 ? 'block' : 'none',
          });
        });
      }
    });

    setInitialColors(0);

    function navigateSlides(next = true) {
      if (isAnimating) return;
      isAnimating = true;

      previousIndex = currentIndex;
      currentIndex = next ? currentIndex + 1 : currentIndex - 1;

      if (!totalSlides) {
        isAnimating = false;
        return;
      }

      const modCurrentIndex =
        ((currentIndex % totalSlides) + totalSlides) % totalSlides;
      const modPreviousIndex =
        ((previousIndex % totalSlides) + totalSlides) % totalSlides;

      animateColors(modCurrentIndex);

      let animationsCompleted = 0;
      const totalAnimations = subSliders.length * 2;

      subSliders.forEach((subSlider, subSliderIndex) => {
        const slides = Array.from(
          subSlider.querySelectorAll('[data-mondriaan-slider-slide]')
        );
        const directionAttr = subSlider.getAttribute('data-mondriaan-sub-slider');

        if (directionAttr === 'fade') {
          const outgoingSlide = slides[modPreviousIndex];
          const incomingSlide = slides[modCurrentIndex];

          gsap.to(outgoingSlide, {
            duration: 1,
            autoAlpha: 0,
            ease: 'primary-ease',
            onComplete: animationCompleted,
          });

          gsap.to(incomingSlide, {
            duration: 0.5,
            autoAlpha: 1,
            delay: 0.25,
            ease: 'primary-ease',
            onComplete: animationCompleted,
          });

          return;
        }

        const fixedDirection = directions[directionAttr];
        let availableDirections = directionKeys;
        let directionKey;

        if (fixedDirection) {
          directionKey = directionAttr;
        } else if (directionAttr === 'random') {
          if (Object.prototype.hasOwnProperty.call(previousDirections, subSliderIndex)) {
            availableDirections = directionKeys.filter(
              (dir) => dir !== previousDirections[subSliderIndex]
            );
          }

          directionKey =
            availableDirections[
              Math.floor(Math.random() * availableDirections.length)
            ];

          previousDirections[subSliderIndex] = directionKey;
        } else {
          directionKey = 'left-right';
        }

        const dirConfig = { ...directions[directionKey] };

        if (!next) {
          dirConfig.multiplier *= -1;
        }

        const outgoingSlide = slides[modPreviousIndex];
        const incomingSlide = slides[modCurrentIndex];
        const offset = 100 * dirConfig.multiplier;
        const otherAxis = dirConfig.axis === 'x' ? 'y' : 'x';

        gsap.set(incomingSlide, {
          [dirConfig.axis]: -offset + '%',
          [otherAxis]: 0,
          display: 'block',
        });

        gsap.to(outgoingSlide, {
          duration: 1,
          [dirConfig.axis]: offset + '%',
          ease: 'primary-ease',
          onComplete: function () {
            gsap.set(outgoingSlide, { display: 'none' });
            animationCompleted();
          },
        });

        gsap.to(incomingSlide, {
          duration: 1,
          [dirConfig.axis]: '0%',
          ease: 'primary-ease',
          onComplete: animationCompleted,
        });
      });

      function animationCompleted() {
        animationsCompleted++;
        if (animationsCompleted >= totalAnimations) {
          isAnimating = false;
        }
      }
    }

    function setInitialColors(index) {
      if (!colors.length) return;

      const color = colors[index % colors.length];
      const targets = slider.querySelectorAll('[data-mondriaan-slider-color-target]');

      targets.forEach((target) => {
        if (color.backgroundColor) {
          target.style.backgroundColor = color.backgroundColor;
        }
        if (color.textColor) {
          target.style.color = color.textColor;
        }
      });
    }

    function animateColors(index) {
      if (!colors.length) return;

      const color = colors[index % colors.length];
      const targets = slider.querySelectorAll('[data-mondriaan-slider-color-target]');

      const animationProps = {
        duration: 1,
        ease: 'primary-ease',
      };

      if (color.backgroundColor) {
        animationProps.backgroundColor = color.backgroundColor;
      }

      if (color.textColor) {
        animationProps.color = color.textColor;
      }

      if (animationProps.backgroundColor || animationProps.color) {
        gsap.to(targets, animationProps);
      }
    }

    const nextButton = slider.querySelector('[data-mondriaan-slider-next]');
    const prevButton = slider.querySelector('[data-mondriaan-slider-prev]');

    if (nextButton) {
      nextButton.addEventListener('click', function () {
        navigateSlides(true);
      });
    }

    if (prevButton) {
      prevButton.addEventListener('click', function () {
        navigateSlides(false);
      });
    }
  });
}

/**
 * Quotes slider
 */
function initQuotesSlider() {
  $('[data-quotes-slider-init]').each(function() {
    var sliderInit = $(this);
    var nextBtn = sliderInit.find('[data-quotes-slider="next"]');
    var prevBtn = sliderInit.find('[data-quotes-slider="prev"]');
    var sliderThree = sliderInit.find('[data-quotes-slider="three"] [role="list"]');
    var sliderOne = sliderInit.find('[data-quotes-slider="one"] [role="list"]');
    var slidesThree = sliderThree.find('[data-quotes-slide]');
    var slidesOne = sliderOne.find('[data-quotes-slide]');

    var isAnimating = false;
    var currentIndex = 0;

    // Calculate total number of slides before cloning
    var totalSlides = slidesThree.length;

    // Format totalSlides as a two-digit number
    var totalSlidesFormatted = totalSlides < 10 ? '0' + totalSlides : totalSlides.toString();

    // Set the formatted total to the element with [data-quotes-slider="total"]
    sliderInit.find('[data-quotes-slider="total"]').text(totalSlidesFormatted);

    // Clone slides to make the slider infinite
    var loopSlides = 2; // Number of slides to clone at each end for looping

    // Clone slides for 'three' slider
    slidesThree.slice(0, loopSlides).clone(true).addClass('clone').appendTo(sliderThree);
    slidesThree.slice(-loopSlides).clone(true).addClass('clone').prependTo(sliderThree);

    // Update slidesThree after cloning
    slidesThree = sliderThree.find('[data-quotes-slide]');
    // Adjust currentIndex to account for cloned slides
    currentIndex += loopSlides;

    // Similarly clone slides for 'one' slider
    slidesOne.slice(0, loopSlides).clone(true).addClass('clone').appendTo(sliderOne);
    slidesOne.slice(-loopSlides).clone(true).addClass('clone').prependTo(sliderOne);

    // Update slidesOne after cloning
    slidesOne = sliderOne.find('[data-quotes-slide]');

    // Function to calculate cumulative positions of slides
    function getSlidePositions(slides) {
      var positions = [0]; // Start with 0
      slides.each(function(i) {
        var slideHeight = $(this).outerHeight(true);
        positions.push(positions[i] + slideHeight);
      });
      return positions;
    }

    // Function to calculate center positions for centering slides
    function getCenterPositions(slides, positions) {
      var centerPositions = [];
      slides.each(function(i) {
        var slideHeight = $(this).outerHeight(true);
        var slideCenterOffset = positions[i] + (slideHeight / 2);
        var translateY = (sliderInit.find('[data-quotes-slider="height"]').height() / 2) - slideCenterOffset;
        centerPositions.push(translateY);
      });
      return centerPositions;
    }

    // Get positions and center positions for both sliders
    var positionsThree = getSlidePositions(slidesThree);
    var positionsOne = getSlidePositions(slidesOne);

    var centerPositionsThree = getCenterPositions(slidesThree, positionsThree);

    // Set the initial position of sliderThree and sliderOne
    gsap.set(sliderThree, { y: centerPositionsThree[currentIndex] });
    gsap.set(sliderOne, { y: -positionsOne[currentIndex] });

    // Update the active class on the center slide
    function updateActiveClass() {
      // Remove active class from all slides
      slidesThree.removeClass('is--active');
      slidesOne.removeClass('is--active');

      // Calculate real index within original slides
      var realIndex = (currentIndex - loopSlides) % totalSlides;
      if (realIndex < 0) realIndex += totalSlides;

      // Apply active class to both original and cloned slides
      slidesThree.each(function(i) {
        var slide = $(this);
        var indexInOriginal = (i - loopSlides) % totalSlides;
        if (indexInOriginal < 0) indexInOriginal += totalSlides;
        if (indexInOriginal === realIndex) {
          slide.addClass('is--active');
        }
      });

      slidesOne.each(function(i) {
        var slide = $(this);
        var indexInOriginal = (i - loopSlides) % totalSlides;
        if (indexInOriginal < 0) indexInOriginal += totalSlides;
        if (indexInOriginal === realIndex) {
          slide.addClass('is--active');
        }
      });
    }

    // Function to slide to a specific index
    function slideTo(index) {
      if (isAnimating) return;
      isAnimating = true;

      // Update currentIndex before starting the animation
      currentIndex = index;

      // Update the active class immediately
      updateActiveClass();

      // Recalculate positions and center positions in case slide heights have changed
      positionsThree = getSlidePositions(slidesThree);
      positionsOne = getSlidePositions(slidesOne);
      centerPositionsThree = getCenterPositions(slidesThree, positionsThree);

      // Animate with GSAP
      var timeline = gsap.timeline({
        onComplete: function() {
          isAnimating = false;

          // Handle infinite looping
          if (currentIndex < loopSlides) {
            // Jump to the corresponding real slide at the end
            currentIndex += totalSlides;
            gsap.set([sliderThree, sliderOne], {
              y: function(i, target) {
                return target === sliderThree.get(0)
                  ? centerPositionsThree[currentIndex]
                  : -positionsOne[currentIndex];
              }
            });
            // No need to update the active class here as we already did
          } else if (currentIndex >= totalSlides + loopSlides) {
            // Jump to the corresponding real slide at the beginning
            currentIndex -= totalSlides;
            gsap.set([sliderThree, sliderOne], {
              y: function(i, target) {
                return target === sliderThree.get(0)
                  ? centerPositionsThree[currentIndex]
                  : -positionsOne[currentIndex];
              }
            });
            // No need to update the active class here as we already did
          }
        }
      });

      // Animate to the new position
      timeline.to([sliderThree, sliderOne], {
        y: function(i, target) {
          return target === sliderThree.get(0)
            ? centerPositionsThree[currentIndex]
            : -positionsOne[currentIndex];
        },
        duration: 1,
        ease: 'primary-ease'
      });
    }

    // Initial call to set the active class
    updateActiveClass();

    // Next button event listener
    nextBtn.on('click', function() {
      slideTo(currentIndex + 1);
    });

    // Prev button event listener
    prevBtn.on('click', function() {
      slideTo(currentIndex - 1);
    });

    // Add click event listeners to the slides
    slidesThree.on('click', function() {
      var clickedIndex = slidesThree.index(this);

      // Prevent interaction if animation is in progress or clicked slide is already active
      if (isAnimating || clickedIndex === currentIndex) return;

      // Slide to the clicked slide
      slideTo(clickedIndex);
    });
  });
}

function initMediaSetup() {
  const mediaElements = document.querySelectorAll("[data-media-init]");
  if (!mediaElements.length) return;

  const pauseDelay = 200;
  const viewportOffset = 0.1;
  const isHoverDevice = window.matchMedia("(hover: hover) and (pointer: fine)").matches;

  initMediaSetup._cleanup?.forEach(fn => fn());
  const cleanupFns = [];
  const rootMarginValue = viewportOffset * 100;

  mediaElements.forEach(mediaEl => {
    const video = mediaEl.querySelector("[data-media-video-src]");
    if (!video) return;

    const mode = mediaEl.dataset.mediaMode || "autoplay";
    const touchMode = mediaEl.dataset.mediaTouchMode;
    const resetAttr = mediaEl.dataset.mediaReset;
    const toggleElements = [...mediaEl.querySelectorAll("[data-media-toggle]")];

    const activeMode = !isHoverDevice ? (touchMode || (mode === "hover" ? "autoplay" : mode)) : mode;
    const shouldResetOnPause = resetAttr === "true" ? true : resetAttr === "false" ? false : activeMode === "hover";

    const clickTargets = toggleElements.length ? toggleElements : [mediaEl];
    const shouldUseClickToggle = activeMode === "click" || (activeMode === "autoplay" && toggleElements.length);

    let isInView = false;
    let isHovering = false;
    let hasLoaded = false;
    let userPaused = false;
    let userActivated = false;
    let isActivated = false;
    let shouldBePlaying = false;
    let pauseTimer = null;

    const setStatus = status => {
      mediaEl.dataset.mediaStatus = status;
    };

    const clearPauseTimer = () => {
      clearTimeout(pauseTimer);
    };

    const addCleanup = fn => {
      cleanupFns.push(fn);
    };

    const on = (target, event, handler) => {
      target.addEventListener(event, handler);
      addCleanup(() => target.removeEventListener(event, handler));
    };

    const playAttempt = () => {
      video.play().then(() => {
        if (shouldBePlaying) setStatus("playing");
      }).catch(() => {});
    };

    const loadVideo = () => {
      if (hasLoaded) return;

      const src = video.dataset.mediaVideoSrc;
      if (!src) return;

      video.muted = true;
      video.playsInline = true;
      video.setAttribute("muted", "");
      video.setAttribute("playsinline", "");
      video.setAttribute("webkit-playsinline", "");
      video.src = src;
      video.load();
      hasLoaded = true;
    };

    const shouldResume = () => {
      if (!isInView || document.hidden) return false;
      if (activeMode === "autoplay") return !userPaused;
      if (activeMode === "click") return userActivated && !userPaused;
      return isHovering;
    };

    const playVideo = () => {
      if (!isInView || document.hidden) return;

      shouldBePlaying = true;
      clearPauseTimer();
      loadVideo();
      setStatus(video.readyState < 3 ? "loading" : "playing");
      playAttempt();
    };

    const pauseVideo = (delay = 0, reset = false) => {
      shouldBePlaying = false;
      clearPauseTimer();

      pauseTimer = setTimeout(() => {
        video.pause();
        if (reset) video.currentTime = 0;
      }, delay);
    };

    const handleHoverIn = () => {
      if (!isInView || document.hidden) return;

      isHovering = true;
      clearPauseTimer();

      if (!video.paused) {
        shouldBePlaying = true;
        setStatus("playing");
        return;
      }

      playVideo();
    };

    const handleHoverOut = () => {
      if (!isInView) return;

      isHovering = false;
      setStatus("not-active");
      pauseVideo(pauseDelay, shouldResetOnPause);
    };

    const handleClick = () => {
      if (!isInView || document.hidden) return;

      clearPauseTimer();

      if (video.paused) {
        userActivated = true;
        userPaused = false;
        playVideo();
      } else {
        userActivated = true;
        userPaused = true;
        setStatus(activeMode === "click" ? "paused" : "not-active");
        pauseVideo(pauseDelay, shouldResetOnPause);
      }
    };

    const handleViewport = entries => {
      entries.forEach(entry => {
        if (entry.target !== mediaEl) return;

        if (!isActivated && entry.isIntersecting) {
          isActivated = true;

          if (shouldUseClickToggle) {
            clickTargets.forEach(toggleEl => on(toggleEl, "click", handleClick));
          }

          if (activeMode === "hover") {
            on(mediaEl, "mouseenter", handleHoverIn);
            on(mediaEl, "mouseleave", handleHoverOut);
          }
        }

        isInView = entry.isIntersecting;

        if (isInView) {
          if (shouldResume()) playVideo();
        } else {
          isHovering = false;

          if (!video.paused || shouldBePlaying) {
            setStatus("paused");
            pauseVideo(0, false);
          }
        }
      });
    };

    const handlePageVisibilityChange = () => {
      if (document.hidden) {
        if (!video.paused || shouldBePlaying) {
          setStatus("paused");
          pauseVideo(0, false);
        }
        return;
      }
      if (shouldResume()) playVideo();
    };

    mediaEl.dataset.mediaStatus = "not-active";

    const observer = new IntersectionObserver(handleViewport, {
      rootMargin: `${rootMarginValue}% 0px ${rootMarginValue}% 0px`,
      threshold: 0
    });

    observer.observe(mediaEl);

    on(video, "playing", () => {if (shouldBePlaying) setStatus("playing");});
    on(video, "waiting", () => {if (shouldBePlaying) setStatus("loading");});
    on(video, "canplay", () => {if (shouldBePlaying && isInView && !document.hidden) playAttempt();});
    on(video, "loadeddata", () => {if (shouldBePlaying && isInView && !document.hidden) playAttempt();});
    on(video, "ended", () => {if (!shouldBePlaying || !isInView || document.hidden) return; video.currentTime = 0; playAttempt();});

    on(document, "visibilitychange", handlePageVisibilityChange);

    addCleanup(() => observer.disconnect());
    addCleanup(() => {
      clearPauseTimer();
      shouldBePlaying = false;
      video.pause();
    });
  });

  initMediaSetup._cleanup = cleanupFns;
}

function initBunnyPlayerBackground() {
  document.querySelectorAll('[data-bunny-background-init]').forEach(function(player) {
    var src = player.getAttribute('data-player-src');
    if (!src) return;

    var video = player.querySelector('video');
    if (!video) return;

    try { video.pause(); } catch(_) {}
    try { video.removeAttribute('src'); video.load(); } catch(_) {}

    // Attribute helpers
    function setStatus(s) {
      if (player.getAttribute('data-player-status') !== s) {
        player.setAttribute('data-player-status', s);
      }
    }
    function setActivated(v) { player.setAttribute('data-player-activated', v ? 'true' : 'false'); }
    if (!player.hasAttribute('data-player-activated')) setActivated(false);

    // Flags
    var lazyMode   = player.getAttribute('data-player-lazy'); // "true" | "false" (no meta)
    var isLazyTrue = lazyMode === 'true';
    var autoplay   = player.getAttribute('data-player-autoplay') === 'true';
    var initialMuted = player.getAttribute('data-player-muted') === 'true';

    // Used to suppress 'ready' flicker when user just pressed play in lazy modes
    var pendingPlay = false;

    // Autoplay forces muted + loop; IO will drive play/pause
    if (autoplay) { video.muted = true; video.loop = true; }
    else { video.muted = initialMuted; }

    video.setAttribute('muted', '');
    video.setAttribute('playsinline', '');
    video.setAttribute('webkit-playsinline', '');
    video.playsInline = true;
    if (typeof video.disableRemotePlayback !== 'undefined') video.disableRemotePlayback = true;
    if (autoplay) video.autoplay = false;

    var isSafariNative = !!video.canPlayType('application/vnd.apple.mpegurl');
    var canUseHlsJs    = !!(window.Hls && Hls.isSupported()) && !isSafariNative;

    // Attach media only once (for actual playback)
    var isAttached = false;
    var userInteracted = false;
    var lastPauseBy = ''; // 'io' | 'manual' | ''
    function attachMediaOnce() {
      if (isAttached) return;
      isAttached = true;

      if (player._hls) { try { player._hls.destroy(); } catch(_) {} player._hls = null; }

      if (isSafariNative) {
        video.preload = isLazyTrue ? 'none' : 'auto';
        video.src = src;
        video.addEventListener('loadedmetadata', function() {
          readyIfIdle(player, pendingPlay);
        }, { once: true });
      } else if (canUseHlsJs) {
        var hls = new Hls({ maxBufferLength: 10 });
        hls.attachMedia(video);
        hls.on(Hls.Events.MEDIA_ATTACHED, function() { hls.loadSource(src); });
        hls.on(Hls.Events.MANIFEST_PARSED, function() {
          readyIfIdle(player, pendingPlay);
        });
        player._hls = hls;
      } else {
        video.src = src;
      }
    }

    // Initialize based on lazy mode
    if (isLazyTrue) {
      video.preload = 'none';
    } else {
      attachMediaOnce();
    }

    // Toggle play/pause
    function togglePlay() {
      userInteracted = true;
      if (video.paused || video.ended) {
        if (isLazyTrue && !isAttached) attachMediaOnce();
        pendingPlay = true;
        lastPauseBy = '';
        setStatus('loading');
        safePlay(video);
      } else {
        lastPauseBy = 'manual';
        video.pause();
      }
    }

    // Toggle mute
    function toggleMute() {
      video.muted = !video.muted;
      player.setAttribute('data-player-muted', video.muted ? 'true' : 'false');
    }

    // Controls (delegated)
    player.addEventListener('click', function(e) {
      var btn = e.target.closest('[data-player-control]');
      if (!btn || !player.contains(btn)) return;
      var type = btn.getAttribute('data-player-control');
      if (type === 'play' || type === 'pause' || type === 'playpause') togglePlay();
      else if (type === 'mute') toggleMute();
    });

    // Media event wiring
    video.addEventListener('play', function() { setActivated(true); setStatus('playing'); });
    video.addEventListener('playing', function() { pendingPlay = false; setStatus('playing'); });
    video.addEventListener('pause', function() { pendingPlay = false; setStatus('paused'); });
    video.addEventListener('waiting', function() { setStatus('loading'); });
    video.addEventListener('canplay', function() { readyIfIdle(player, pendingPlay); });
    video.addEventListener('ended', function() { pendingPlay = false; setStatus('paused'); setActivated(false); });

    // In-view auto play/pause (only when autoplay is true)
    if (autoplay) {
      if (player._io) { try { player._io.disconnect(); } catch(_) {} }
      var io = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
          var inView = entry.isIntersecting && entry.intersectionRatio > 0;
          if (inView) {
            if (isLazyTrue && !isAttached) attachMediaOnce();
            if ((lastPauseBy === 'io') || (video.paused && lastPauseBy !== 'manual')) {
              setStatus('loading');
              if (video.paused) togglePlay();
              lastPauseBy = '';
            }
          } else {
            if (!video.paused && !video.ended) {
              lastPauseBy = 'io';
              video.pause();
            }
          }
        });
      }, { threshold: 0.1 });
      io.observe(player);
      player._io = io;
    }
  });

  // Helper: Ready status guard
  function readyIfIdle(player, pendingPlay) {
    if (!pendingPlay &&
        player.getAttribute('data-player-activated') !== 'true' &&
        player.getAttribute('data-player-status') === 'idle') {
      player.setAttribute('data-player-status', 'ready');
    }
  }

  // Helper: safe programmatic play
  function safePlay(video) {
    var p = video.play();
    if (p && typeof p.then === 'function') p.catch(function(){});
  }
}

